window.kbPageData["views/entry/k-741680e376fea3e3"] = {"key":"entry/k-741680e376fea3e3","state":{"route":"entry/k-741680e376fea3e3"},"node":{"id":"k-741680e376fea3e3","mode":"k","title":"不动产善意取得","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["不动产善意取得须具备受让时善意、合理价格和完成登记"],"qs":["国考 2024 行政执法 行测#14"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"公开回忆版同样只写“支付对价”。仍需核对正式题文是否另有价格合理的条件。若无补充，选项C依赖题文未明示的前提。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"原题引文：小王支付对价并办理了产权变更手续","review":{"definition":"原题引文：小王支付对价并办理了产权变更手续","explanation":"本题给出小王不知情、支付对价和办妥产权变更登记。标准答案C隐含交易价格合理这一前提，无权处分本身不影响买卖合同效力。在满足善意取得条件时，小王取得房屋所有权，老张可向无处分权的小张请求赔偿。合理价格须结合转让时当地市场价格、付款方式及交易习惯等认定，题文仅写“支付对价”，价格条件仍缺乏事实支持。","references":[{"source":"web-f4e85f00d16e5fcc","location":"第三百一十一条第一、二款","quote":"以合理的价格转让"},{"source":"web-b738d581015976df","location":"第十八条","quote":"参考转让时交易地市场价格以及交易习惯"}],"evidence":"小王支付对价并办理了产权变更手续","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"国考 2024 行政执法 行测#14":{"paper":"国考 2024 行政执法 行测","n":14,"mod":"常识判断","src":["dfddc59dc6e7d9da5d71.pdf",3],"asrc":["6493f3a6a55c38431852.pdf",5],"card":"373d3c8b70e80f36d9d3207c","links":[{"id":"k-741680e376fea3e3","role":"直接考查","why":"以受让时善意、合理价格和完成登记三项条件判断受让人是否取得房屋所有权。"}]}},"terms":{},"references":{"web-f4e85f00d16e5fcc":{"name":"《中华人民共和国民法典》","url":"https://www.cac.gov.cn/2020-06/01/c_15925617772683191.htm"},"web-b738d581015976df":{"name":"最高人民法院《关于适用〈中华人民共和国民法典〉物权编的解释（一）》","url":"https://www.court.gov.cn/zixun/xiangqing/282101.html"}},"topics":[],"units":{"k-741680e376fea3e3":[["国考 2024 行政执法 行测#14"]]}};
